    phaseOne.conversationId=response.conversationId||phaseOne.conversationId;thread.push({role:'assistant',content:result.answer,result,model:response.model,gameVersion:response.gameVersion,generatedAt:response.generatedAt,applied:false,draftId:response.draft?.id||null,resolutionSessionId:response.resolutionSession?.id||null});if(response.draft||response.resolutionSession)await refreshAiGmData();setCopilotStatus(result.requires_gm_decision?'Answer ready. The cited sources leave a decision for the GM.':'Answer ready. Review any proposed changes before applying them.','success');
